import zipfile
import xml.etree.ElementTree as ET

M = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'

def col_idx(ref):
    letters = ''.join(ch for ch in ref if ch.isalpha())
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx

def row_idx(ref):
    return int(''.join(ch for ch in ref if ch.isdigit()))

expenses = []  # (row, category, subcategory, amount)
with zipfile.ZipFile('budget.xlsx') as z:
    sroot = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
    for c in sroot.iter(f'{{{M}}}c'):
        t = c.get('t')
        if t != 'inlineStr':
            continue
        texts = [el.text or '' for el in c.iter(f'{{{M}}}t')]
        row = row_idx(c.get('r'))
        col = col_idx(c.get('r'))
        text = ''.join(texts)
        # collect category (A) and subcategory (B) labels; C holds amounts
        if row >= 11 and row <= 22:
            if col == 1:
                expenses.append({'row': row, 'category': text, 'sub': None, 'amount': None})
            elif col == 2:
                for e in reversed(expenses):
                    if e['row'] == row:
                        e['sub'] = text
                        break
            elif col == 3:
                v = c.find(f'{{{M}}}v')
                for e in reversed(expenses):
                    if e['row'] == row:
                        e['amount'] = float(v.text)
                        break

print("Expense line items:")
total = 0.0
for e in sorted(expenses, key=lambda x: x['row']):
    print(f"  {e['category']:<15} {e['sub']:<16} {e['amount']:>8.2f}")
    total += e['amount']
print(f"\nTotal expenses (all categories): {total:,.2f}")

by_cat = {}
for e in expenses:
    by_cat[e['category']] = by_cat.get(e['category'], 0.0) + e['amount']
print("\nBy category:")
for cat, amt in sorted(by_cat.items()):
    print(f"  {cat:<15} {amt:>8.2f}")
print(f"  {'TOTAL':<15} {sum(by_cat.values()):>8.2f}")

